#include <stdio.h>
#include <string.h>

int main() {
    int n;
    scanf("%d", &n);
    int a[50][50];
    int reach[50][50] = {0};

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            scanf("%d", &a[i][j]);
        }
    }

    // Build direct win graph
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j) {
                // If A[i][j] == 1, i beats j
                if (a[i][j] == 1)
                    reach[i][j] = 1;
            }
        }
    }

    // Floyd-Warshall for transitive closure
    for (int k = 0; k < n; k++) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (reach[i][k] && reach[k][j])
                    reach[i][j] = 1;
            }
        }
    }

    int count = 0;
    for (int i = 0; i < n; i++) {
        int can = 1;
        for (int j = 0; j < n; j++) {
            if (i != j && !reach[i][j]) {
                can = 0;
                break;
            }
        }
        if (can) count++;
    }

    printf("%d\n", count);
    return 0;
}

