#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    char **A = (char **)malloc(N * sizeof(char *));
    for (int i = 0; i < N; i++) {
        A[i] = (char *)malloc((N + 5) * sizeof(char));
        scanf("%s", A[i]);
    }

    /* dp[l][r][k] = 1 if person k (0-based, l<=k<=r) can become champion
       of the contiguous segment [l..r].
       Since only persons inside [l..r] matter, store as bitset over N. */

    int words = (N + 63) / 64;
    unsigned long long ***dp = (unsigned long long ***)malloc(N * sizeof(unsigned long long **));
    for (int l = 0; l < N; l++) {
        dp[l] = (unsigned long long **)malloc(N * sizeof(unsigned long long *));
        for (int r = 0; r < N; r++) {
            dp[l][r] = (unsigned long long *)calloc(words, sizeof(unsigned long long));
        }
    }

    for (int i = 0; i < N; i++) {
        dp[i][i][i >> 6] |= 1ULL << (i & 63);
    }

    for (int len = 2; len <= N; len++) {
        for (int l = 0; l + len - 1 < N; l++) {
            int r = l + len - 1;

            for (int m = l; m < r; m++) {
                unsigned long long *L = dp[l][m];
                unsigned long long *R = dp[m + 1][r];

                for (int i = l; i <= m; i++) {
                    if (((L[i >> 6] >> (i & 63)) & 1ULL) == 0) continue;
                    for (int j = m + 1; j <= r; j++) {
                        if (((R[j >> 6] >> (j & 63)) & 1ULL) == 0) continue;

                        if (A[i][j] == '1') {
                            dp[l][r][i >> 6] |= 1ULL << (i & 63);
                        } else {
                            dp[l][r][j >> 6] |= 1ULL << (j & 63);
                        }
                    }
                }
            }
        }
    }

    int ans = 0;
    for (int i = 0; i < N; i++) {
        if ((dp[0][N - 1][i >> 6] >> (i & 63)) & 1ULL) ans++;
    }

    printf("%d\n", ans);

    for (int l = 0; l < N; l++) {
        for (int r = 0; r < N; r++) free(dp[l][r]);
        free(dp[l]);
    }
    free(dp);

    for (int i = 0; i < N; i++) free(A[i]);
    free(A);

    return 0;
}

