using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<int>> win(N, vector<int>(N, 0));

    // Input format:
    // For each i < j, A_{i,j} is given.
    // A_{i,j} = 1 => i beats j
    // A_{i,j} = 0 => j beats i
    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            int a;
            cin >> a;
            if (a == 1) {
                win[i][j] = 1;
                win[j][i] = 0;
            } else {
                win[i][j] = 0;
                win[j][i] = 1;
            }
        }
    }

    // dp[l][r][x] = whether person x (l <= x <= r) can become champion
    // from the contiguous segment [l, r].
    vector<vector<bitset<200>>> dp(N, vector<bitset<200>>(N));

    for (int i = 0; i < N; ++i) dp[i][i].set(i);

    for (int len = 2; len <= N; ++len) {
        for (int l = 0; l + len - 1 < N; ++l) {
            int r = l + len - 1;

            for (int m = l; m < r; ++m) {
                // left segment [l, m], right segment [m+1, r]
                // Any champion from left can survive if it beats some possible champion from right.
                // Any champion from right can survive if it beats some possible champion from left.
                for (int x = l; x <= m; ++x) {
                    if (!dp[l][m].test(x)) continue;
                    for (int y = m + 1; y <= r; ++y) {
                        if (!dp[m + 1][r].test(y)) continue;
                        if (win[x][y]) dp[l][r].set(x);
                        else dp[l][r].set(y);
                    }
                }
            }
        }
    }

    cout << dp[0][N - 1].count() << '\n';
    return 0;
}

