public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int[][] win = new int[N][N];

        for (int i = 0; i < N; i++) {
            String s = fs.next();
            if (s.length() == N) {
                for (int j = 0; j < N; j++) {
                    win[i][j] = s.charAt(j) - '0';
                }
            } else {
                win[i][0] = Integer.parseInt(s);
                for (int j = 1; j < N; j++) win[i][j] = fs.nextInt();
            }
        }

        BitSet[][] dp = new BitSet[N][N];
        for (int i = 0; i < N; i++) {
            dp[i][i] = new BitSet(N);
            dp[i][i].set(i);
        }

        for (int len = 2; len <= N; len++) {
            for (int l = 0; l + len - 1 < N; l++) {
                int r = l + len - 1;
                BitSet res = new BitSet(N);

                for (int m = l; m < r; m++) {
                    BitSet left = dp[l][m];
                    BitSet right = dp[m + 1][r];
                    if (left == null || right == null) continue;

                    for (int i = left.nextSetBit(0); i >= 0; i = left.nextSetBit(i + 1)) {
                        boolean ok = false;
                        for (int j = right.nextSetBit(0); j >= 0; j = right.nextSetBit(j + 1)) {
                            if (win[i][j] == 1) {
                                ok = true;
                                break;
                            }
                        }
                        if (ok) res.set(i);
                    }

                    for (int j = right.nextSetBit(0); j >= 0; j = right.nextSetBit(j + 1)) {
                        boolean ok = false;
                        for (int i = left.nextSetBit(0); i >= 0; i = left.nextSetBit(i + 1)) {
                            if (win[j][i] == 1) {
                                ok = true;
                                break;
                            }
                        }
                        if (ok) res.set(j);
                    }
                }

                dp[l][r] = res;
            }
        }

        System.out.println(dp[0][N - 1].cardinality());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

